from datetime import datetime

# Una traza ya con ids nuevos: raíz R, hijo A (LLM) y nieto B (tool dentro de A)
trace_runs = [
    {"id": "B", "parent_run_id": "A",  "start_time": datetime(2026, 11, 11, 18, 0, 2)},
    {"id": "R", "parent_run_id": None, "start_time": datetime(2026, 11, 11, 18, 0, 0)},
    {"id": "A", "parent_run_id": "R",  "start_time": datetime(2026, 11, 11, 18, 0, 1)},
]

# Raíz primero; después los hijos por hora de inicio
trace_runs.sort(key=lambda r: (r["parent_run_id"] is not None, r["start_time"]))

dotted_orders = {}
for run in trace_runs:
    ts = run["start_time"].strftime("%Y%m%dT%H%M%S%f") + "Z"
    if run["parent_run_id"] is None:
        run["dotted_order"] = f"{ts}{run['id']}"
    else:
        parent_order = dotted_orders.get(run["parent_run_id"], "")
        run["dotted_order"] = f"{parent_order}.{ts}{run['id']}"
    dotted_orders[run["id"]] = run["dotted_order"]

for run in trace_runs:
    print(run["id"], "->", run["dotted_order"])
